        async fn activity_list(
            &self,
            request: Request<economy_proto::ActivityListRequest>,
        ) -> std::result::Result<Response<economy_proto::ActivityListResponse>, Status> {
            // 2026-10-03 接线: v1 空壳 → v3 ActivityService::activity_list (真有逻辑)
            let req = request.into_inner();
            let out = self
                .shop
                .activity_list(
                    req.player_id,
                    req.page.max(0) as u32,
                    req.page_size.max(1) as u32,
                    req.active_only,
                )
                .await
                .map_err(Into::<tonic::Status>::into)?;
            Ok(Response::new(economy_proto::ActivityListResponse {
                templates: out.templates.iter().map(activity_to_proto).collect(),
                total: out.total,
                active_count: out.active_count,
            }))
        }

